   "\nCREATE INDEX \"recharge_events_rc\" ON \"recharge_events\" USING btree (\"recharge_id\",\"created_at\");",
   "\nCREATE INDEX \"staff_alerts_created\" ON \"staff_alerts\" USING btree (\"created_at\");",
   "\nCREATE UNIQUE INDEX \"recharges_provider_order\" ON \"recharges\" USING btree (\"method\",\"provider_order_id\");",
   "\nCREATE UNIQUE INDEX \"recharges_utr_credited\" ON \"recharges\" USING btree (\"utr\") WHERE \"recharges\".\"status\" = 'credited' and \"recharges\".\"method\" = 'manual';",
   "\nCREATE INDEX \"recharges_org_created\" ON \"recharges\" USING btree (\"org_id\",\"created_at\");",
   "\nCREATE INDEX \"recharges_status\" ON \"recharges\" USING btree (\"status\");",
   "\nALTER TABLE \"recharges\" ADD CONSTRAINT \"recharges_request_number_unique\" UNIQUE(\"request_number\");",
   "\nUPDATE \"recharges\" SET \"status\" = 'credited' WHERE \"status\" = 'captured';",
   "\nUPDATE \"recharges\" SET \"status\" = 'payment_pending' WHERE \"status\" = 'pending';",
   "\nUPDATE \"recharges\" SET \"method\" = 'demo' WHERE \"razorpay_order_id\" LIKE 'demo_%';",
