   "\nCREATE TABLE \"email_templates\" (\n\t\"event\" text PRIMARY KEY NOT NULL,\n\t\"subject\" text NOT NULL,\n\t\"body\" text NOT NULL,\n\t\"updated_by\" text,\n\t\"updated_at\" timestamp with time zone DEFAULT now() NOT NULL\n);\n",
